"use client";

import { useMemo, useState } from "react";
import Link from "next/link";
import { Activity, AlertTriangle, BookOpen, CalendarDays, Check, CheckCircle2, ChevronRight, CircleUserRound, ClipboardCheck, Clock3, Download, File, FileText, Filter, FolderOpen, HeartHandshake, Info, ListChecks, ListTodo, Megaphone, MessageSquareText, Paperclip, Plus, Save, Search, Send, TrendingUp, Upload, UserCheck, UsersRound, Video } from "lucide-react";
import { Dashboard } from "./dashboards";
import { DistributionChart, PerformanceChart, SchoolTrendChart, SubjectChart } from "./charts";
import { Avatar, Button, Insight, PageHeader, ProgressBar, SectionHeader, StatCard, StatusBadge } from "./ui";
import { activities, assessments, classes, notifications, performance, profiles, schedule, students, subjects } from "@/lib/mock-data";
import type { Role, Tone } from "@/lib/types";

export function Workspace({ role, slug }: { role: Role; slug: string[] }) {
  const path = slug.join("/");
  if (!path) return <Dashboard role={role} />;
  if (slug[0] === "perfil") return role === "student" ? <ProfilePage /> : <AccountSettings role={role} />;
  if (role === "student") return <StudentPage page={slug[0]} />;
  if (role === "parent") return <ParentPage page={slug[0]} />;
  if (role === "teacher") return <TeacherPage page={slug[0]} id={slug[1]} />;
  if (role === "coordinator") return <CoordinatorPage page={slug[0]} id={slug[1]} />;
  return <DirectorPage page={slug[0]} id={slug[1]} />;
}

function AccountSettings({ role }: { role: Role }) {
  const profile = profiles[role];
  const [toast, setToast] = useState(false);
  return <div className="page-enter"><PageHeader eyebrow="Conta" title="Configurações do perfil" description="Preferências do ambiente demonstrativo e informações da conta." /><div className="grid gap-4 lg:grid-cols-[300px_1fr]"><section className="card soft-shadow p-6 text-center"><Avatar index={profile.avatar} size="xl" className="mx-auto" /><h2 className="mt-4 text-lg font-bold">{profile.name}</h2><p className="mt-1 text-xs text-slate-500">{profile.subtitle}</p><StatusBadge tone="info">Conta demo</StatusBadge></section><section className="card soft-shadow p-5"><SectionHeader title="Preferências" /><div className="space-y-3">{[["Notificações acadêmicas", "Notas, faltas e atividades"], ["Comunicados da escola", "Avisos e calendário"], ["Resumo semanal", "Panorama enviado às segundas"]].map(([title, detail]) => <label key={title} className="flex items-center justify-between rounded-md border p-4"><span><strong className="block text-xs">{title}</strong><small className="mt-1 block text-[10px] text-slate-500">{detail}</small></span><input type="checkbox" defaultChecked className="h-4 w-4 accent-blue-700" /></label>)}</div><div className="mt-5 flex justify-end"><Button icon={Save} onClick={() => setToast(true)}>Salvar preferências</Button></div></section></div>{toast && <DemoToast message="Preferências atualizadas no ambiente demonstrativo." onClose={() => setToast(false)} />}</div>;
}

function Toolbar({ children }: { children?: React.ReactNode }) {
  return <div className="mb-5 flex flex-wrap items-center gap-2 rounded-lg border border-slate-200 bg-white p-3">{children}</div>;
}

function Select({ label, children, value, onChange }: { label: string; children: React.ReactNode; value?: string; onChange?: (value: string) => void }) {
  return <label className="min-w-36 flex-1 sm:flex-none"><span className="mb-1.5 block text-[10px] font-semibold text-slate-500">{label}</span><select value={value} onChange={(e) => onChange?.(e.target.value)} className="h-9 w-full rounded-md border border-slate-200 bg-white px-3 text-xs font-medium text-slate-700"><>{children}</></select></label>;
}

function DemoToast({ message, onClose }: { message: string; onClose: () => void }) {
  return <div role="status" className="fixed bottom-20 right-4 z-[80] flex max-w-sm items-center gap-3 rounded-lg bg-slate-900 px-4 py-3 text-xs text-white shadow-xl lg:bottom-5"><CheckCircle2 className="h-4 w-4 text-emerald-400" /><span>{message}</span><button onClick={onClose} className="ml-2 text-slate-400">×</button></div>;
}

function StudentPage({ page }: { page: string }) {
  if (page === "notas") return <GradesPage />;
  if (page === "boletim") return <ReportCardPage />;
  if (page === "frequencia") return <AttendancePage />;
  if (page === "horario") return <SchedulePage />;
  if (page === "avaliacoes") return <AssessmentsPage />;
  if (page === "atividades") return <ActivitiesPage />;
  if (page === "materiais") return <MaterialsPage />;
  if (page === "calendario") return <CalendarPage />;
  if (page === "ocorrencias") return <RecordsPage />;
  if (page === "avisos") return <AnnouncementsPage />;
  return <ProfilePage />;
}

const gradeRows = subjects.map((subject, index) => ({ ...subject, p1: [8.5, 7.5, 9, 8, 9.5, 7.5][index], p2: [8, 7, 9.2, 8.5, 8.8, 7.8][index], work: [9.5, 9, 8.8, 8, 8.5, 8][index], mock: [8.8, 8, 9, 8.2, 8.9, 7.9][index] }));

function scoreTone(score: number): Tone { return score >= 8.5 ? "success" : score >= 7 ? "info" : score >= 6 ? "warning" : "danger"; }
function scoreLabel(score: number) { return score >= 8.5 ? "Excelente" : score >= 7 ? "Bom" : score >= 6 ? "Atenção" : "Abaixo da média"; }

function GradesPage() {
  const [term, setTerm] = useState("3º bimestre");
  return <div className="page-enter"><PageHeader eyebrow="Vida acadêmica" title="Minhas notas" description="Acompanhe seu desempenho em cada disciplina e avaliação." /><Toolbar><Select label="Ano letivo"><option>2026</option><option>2025</option></Select><Select label="Período" value={term} onChange={setTerm}><option>1º bimestre</option><option>2º bimestre</option><option>3º bimestre</option><option>4º bimestre</option></Select><div className="ml-auto hidden text-xs text-slate-500 sm:block">Média mínima: <strong className="text-slate-800">6,0</strong></div></Toolbar><section className="card soft-shadow overflow-hidden"><div className="desktop-table table-wrap"><table className="data-table"><thead><tr><th>Disciplina</th><th>Avaliação 1</th><th>Avaliação 2</th><th>Trabalho</th><th>Simulado</th><th>Média</th><th>Situação</th></tr></thead><tbody>{gradeRows.map((row) => <tr key={row.name}><td><p className="font-semibold text-slate-800">{row.name}</p><p className="mt-1 text-[10px] text-slate-400">{row.teacher}</p></td><td>{row.p1.toFixed(1).replace(".", ",")}</td><td>{row.p2.toFixed(1).replace(".", ",")}</td><td>{row.work.toFixed(1).replace(".", ",")}</td><td>{row.mock.toFixed(1).replace(".", ",")}</td><td><strong>{row.score.toFixed(1).replace(".", ",")}</strong></td><td><StatusBadge tone={scoreTone(row.score)}>{scoreLabel(row.score)}</StatusBadge></td></tr>)}</tbody></table></div><div className="mobile-cards gap-3 p-3">{gradeRows.map((row) => <article key={row.name} className="rounded-lg border border-slate-200 p-4"><div className="flex items-start justify-between"><div><p className="text-sm font-bold">{row.name}</p><p className="mt-1 text-[11px] text-slate-500">{row.teacher}</p></div><div className="text-right"><p className="text-xl font-bold">{row.score.toFixed(1).replace(".", ",")}</p><StatusBadge tone={scoreTone(row.score)}>{scoreLabel(row.score)}</StatusBadge></div></div><div className="mt-4 grid grid-cols-4 gap-2 border-t pt-3 text-center"><MiniGrade label="Av. 1" value={row.p1} /><MiniGrade label="Av. 2" value={row.p2} /><MiniGrade label="Trab." value={row.work} /><MiniGrade label="Sim." value={row.mock} /></div></article>)}</div></section></div>;
}

function MiniGrade({ label, value }: { label: string; value: number }) { return <div><p className="text-[9px] text-slate-400">{label}</p><p className="mt-1 text-xs font-bold">{value.toFixed(1).replace(".", ",")}</p></div>; }

function ReportCardPage() {
  const [toast, setToast] = useState(false);
  return <div className="page-enter"><PageHeader eyebrow="Documento acadêmico" title="Boletim digital" description="Notas, frequência e situação em todos os períodos." action={<Button icon={Download} variant="secondary" onClick={() => setToast(true)}>Baixar boletim</Button>} /><section className="card soft-shadow overflow-hidden"><div className="border-b border-slate-100 p-5"><div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><Avatar index={0} /><div><p className="text-sm font-bold">Lucas Silva</p><p className="text-[11px] text-slate-500">8º A · Matrícula 20261031</p></div></div><StatusBadge tone="success">Situação regular</StatusBadge></div></div><div className="table-wrap"><table className="data-table"><thead><tr><th>Disciplina</th><th>1º Bim.</th><th>2º Bim.</th><th>3º Bim.</th><th>4º Bim.</th><th>Frequência</th><th>Média final</th><th>Situação</th></tr></thead><tbody>{subjects.map((subject, index) => <tr key={subject.name}><td className="font-semibold">{subject.name}</td><td>{(subject.score - .6).toFixed(1).replace(".", ",")}</td><td>{(subject.score - .2).toFixed(1).replace(".", ",")}</td><td>{subject.score.toFixed(1).replace(".", ",")}</td><td className="text-slate-400">—</td><td>{[96, 92, 98, 94, 95, 91][index]}%</td><td><strong>{(subject.score - .2).toFixed(1).replace(".", ",")}</strong></td><td><StatusBadge tone="success">Aprovado parcial</StatusBadge></td></tr>)}</tbody></table></div></section>{toast && <DemoToast message="Boletim preparado. A exportação em PDF será conectada na próxima etapa." onClose={() => setToast(false)} />}</div>;
}

function AttendancePage() {
  const monthly = [{ month: "Fev", value: 96 }, { month: "Mar", value: 92 }, { month: "Abr", value: 91 }, { month: "Mai", value: 95 }, { month: "Jun", value: 93 }, { month: "Ago", value: 96 }, { month: "Set", value: 94 }];
  return <div className="page-enter"><PageHeader eyebrow="Vida acadêmica" title="Frequência" description="Acompanhe sua presença nas aulas e faltas registradas." /><div className="grid grid-cols-2 gap-3 lg:grid-cols-5"><StatCard label="Frequência geral" value="94%" detail="Meta: 80%" icon={UserCheck} tone="success" /><StatCard label="Total de aulas" value="450" detail="Até 24 de setembro" icon={BookOpen} /><StatCard label="Aulas frequentadas" value="423" detail="Presenças registradas" icon={CheckCircle2} tone="success" /><StatCard label="Faltas" value="7" detail="5 não justificadas" icon={AlertTriangle} tone="warning" /><StatCard label="Justificadas" value="2" detail="Documentos aceitos" icon={FileText} tone="neutral" /></div><div className="mt-4 grid gap-4 xl:grid-cols-[.8fr_1.2fr]"><section className="card soft-shadow p-5"><SectionHeader title="Frequência mensal" /><div className="space-y-4">{monthly.map((m) => <ProgressBar key={m.month} value={m.value} label={m.month} tone={m.value >= 90 ? "success" : "warning"} />)}</div></section><section className="card soft-shadow overflow-hidden"><div className="p-5 pb-2"><SectionHeader title="Registros recentes" /></div><div className="table-wrap"><table className="data-table"><thead><tr><th>Data</th><th>Disciplina</th><th>Professor</th><th>Situação</th></tr></thead><tbody>{[["22/09/2026", "Matemática", "Rafael Almeida", "Presente", "success"], ["21/09/2026", "História", "Paulo Mendes", "Falta justificada", "info"], ["18/09/2026", "Ciências", "Beatriz Santos", "Falta", "danger"], ["17/09/2026", "Português", "Juliana Costa", "Presente", "success"]].map((r) => <tr key={`${r[0]}${r[1]}`}><td>{r[0]}</td><td className="font-semibold">{r[1]}</td><td>{r[2]}</td><td><StatusBadge tone={r[4] as Tone}>{r[3]}</StatusBadge></td></tr>)}</tbody></table></div></section></div></div>;
}

function SchedulePage() {
  const days = ["Segunda", "Terça", "Quarta", "Quinta", "Sexta"];
  return <div className="page-enter"><PageHeader eyebrow="Rotina" title="Horário de aulas" description="Sua grade semanal · 8º A · turno da manhã" /><div className="mobile-scroll overflow-x-auto pb-2"><div className="grid min-w-[900px] grid-cols-5 gap-3">{days.map((day, dayIndex) => <section key={day} className="card overflow-hidden"><div className={`border-b p-3 ${dayIndex === 3 ? "bg-blue-700 text-white" : "bg-slate-50"}`}><p className="text-center text-xs font-bold">{day}</p></div><div className="divide-y divide-slate-100">{schedule.map((row, index) => { const shifted = schedule[(index + dayIndex) % schedule.length]; return <div key={row[0]} className="p-3"><p className="text-[10px] font-semibold text-blue-700">{row[0]}</p><p className="mt-1 text-xs font-bold">{shifted[1]}</p><p className="mt-1 text-[10px] text-slate-500">{shifted[2]}</p><p className="mt-2 text-[9px] text-slate-400">Sala {shifted[3]}</p></div>; })}</div></section>)}</div></div></div>;
}

function AssessmentsPage() {
  return <div className="page-enter"><PageHeader eyebrow="Calendário acadêmico" title="Avaliações" description="Prepare-se para as próximas avaliações e consulte seu histórico." /><div className="grid gap-3 md:grid-cols-3">{assessments.map((item, index) => <article key={item.subject} className="card soft-shadow p-5"><div className="flex items-center justify-between"><div className="grid h-10 w-10 place-items-center rounded-md bg-blue-50"><ClipboardCheck className="h-5 w-5 text-blue-700" /></div><span className="text-right"><strong className="block text-sm text-blue-700">{item.date}</strong><small className="text-[10px] text-slate-400">{item.time}</small></span></div><p className="mt-5 text-sm font-bold">{item.subject}</p><p className="mt-1 text-xs text-slate-500">{item.title}</p><div className="mt-4 rounded-md bg-slate-50 p-3"><p className="text-[9px] font-bold uppercase text-slate-400">Conteúdo</p><p className="mt-1 text-[11px] text-slate-600">{item.content}</p></div><div className="mt-4"><StatusBadge tone={index === 0 ? "warning" : "info"}>{index === 0 ? "Amanhã" : `Em ${index * 3 + 3} dias`}</StatusBadge></div></article>)}</div><section className="card soft-shadow mt-4 overflow-hidden"><div className="p-5 pb-2"><SectionHeader title="Histórico de avaliações" /></div><div className="table-wrap"><table className="data-table"><thead><tr><th>Data</th><th>Disciplina</th><th>Avaliação</th><th>Valor</th><th>Nota</th><th>Situação</th></tr></thead><tbody>{subjects.slice(0, 4).map((s, i) => <tr key={s.name}><td>{["12/09", "10/09", "05/09", "29/08"][i]}</td><td className="font-semibold">{s.name}</td><td>Atividade avaliativa</td><td>10,0</td><td><strong>{s.score.toFixed(1).replace(".", ",")}</strong></td><td><StatusBadge tone={scoreTone(s.score)}>{scoreLabel(s.score)}</StatusBadge></td></tr>)}</tbody></table></div></section></div>;
}

function ActivitiesPage() {
  const [filter, setFilter] = useState("Todas");
  const visible = filter === "Todas" ? activities : activities.filter((a) => a.status === filter);
  return <div className="page-enter"><PageHeader eyebrow="Aprendizagem" title="Atividades" description="Organize entregas, anexos e devolutivas dos professores." /><div className="mb-4 flex gap-2 overflow-x-auto pb-1">{["Todas", "Pendente", "Entregue", "Corrigida", "Atrasada"].map((item) => <button key={item} onClick={() => setFilter(item)} className={`h-9 whitespace-nowrap rounded-md border px-3 text-xs font-semibold ${filter === item ? "border-blue-700 bg-blue-700 text-white" : "border-slate-200 bg-white text-slate-600"}`}>{item}</button>)}</div><div className="grid gap-3 lg:grid-cols-2">{visible.map((item) => <article key={item.title} className="card soft-shadow p-5"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-semibold text-blue-700">{item.subject}</p><h2 className="mt-1 text-sm font-bold">{item.title}</h2><p className="mt-1 text-[11px] text-slate-500">Prof. {item.teacher}</p></div><StatusBadge tone={item.tone as Tone}>{item.status}</StatusBadge></div><p className="mt-4 text-xs leading-5 text-slate-600">Produza a atividade conforme as orientações publicadas no material de apoio.</p><div className="mt-4 flex flex-wrap items-center gap-4 border-t pt-3 text-[10px] text-slate-500"><span className="flex items-center gap-1"><Clock3 className="h-3 w-3" />Prazo: {item.due}</span><span className="flex items-center gap-1"><Paperclip className="h-3 w-3" />2 anexos</span>{item.score !== "—" && <span>Nota: <strong>{item.score}</strong></span>}</div></article>)}</div></div>;
}

function MaterialsPage() {
  const materialIcons = [FileText, Video, File, FolderOpen, FileText, Video];
  return <div className="page-enter"><PageHeader eyebrow="Biblioteca de aula" title="Materiais" description="Conteúdos compartilhados pelos seus professores." /><Toolbar><Select label="Disciplina"><option>Todas as disciplinas</option>{subjects.map((s) => <option key={s.name}>{s.name}</option>)}</Select><label className="min-w-52 flex-1"><span className="mb-1.5 block text-[10px] font-semibold text-slate-500">Buscar material</span><div className="flex h-9 items-center gap-2 rounded-md border border-slate-200 px-3"><Search className="h-4 w-4 text-slate-400" /><input className="w-full border-0 text-xs outline-none" placeholder="Título ou professor" /></div></label></Toolbar><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{subjects.map((subject, index) => { const Icon = materialIcons[index]; return <article key={subject.name} className="card soft-shadow flex gap-4 p-4"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-md bg-blue-50"><Icon className="h-5 w-5 text-blue-700" /></div><div className="min-w-0"><p className="text-sm font-bold">{["Guia de estudos", "Aula gravada: equações", "Linha do tempo", "Mapas e escalas", "Lista de exercícios", "Listening practice"][index]}</p><p className="mt-1 text-[11px] text-slate-500">{subject.name} · {subject.teacher}</p><p className="mt-3 text-[10px] text-slate-400">Publicado em {18 + index}/09 · PDF</p></div></article>; })}</div></div>;
}

function CalendarPage() {
  const events = [{ day: 25, title: "Prova de Matemática", type: "Prova", tone: "info" }, { day: 28, title: "Projeto de Ciências", type: "Entrega", tone: "success" }, { day: 30, title: "Reunião de responsáveis", type: "Reunião", tone: "warning" }, { day: 3, title: "Feira cultural", type: "Evento", tone: "neutral" }];
  const blanks = Array.from({ length: 2 });
  return <div className="page-enter"><PageHeader eyebrow="Ano letivo 2026" title="Calendário escolar" description="Aulas, provas, reuniões e eventos importantes." /><div className="grid gap-4 xl:grid-cols-[1fr_320px]"><section className="card soft-shadow p-4 md:p-5"><div className="mb-5 flex items-center justify-between"><button className="h-8 rounded-md border px-3 text-xs">Anterior</button><h2 className="text-sm font-bold">Setembro 2026</h2><button className="h-8 rounded-md border px-3 text-xs">Próximo</button></div><div className="grid grid-cols-7 border-l border-t border-slate-200">{["Seg", "Ter", "Qua", "Qui", "Sex", "Sáb", "Dom"].map((d) => <div key={d} className="border-b border-r bg-slate-50 p-2 text-center text-[10px] font-bold text-slate-500">{d}</div>)}{blanks.map((_, i) => <div key={`b${i}`} className="min-h-20 border-b border-r bg-slate-50/40" />)}{Array.from({ length: 30 }, (_, i) => i + 1).map((day) => { const event = events.find((e) => e.day === day); return <div key={day} className={`min-h-20 border-b border-r p-2 ${day === 24 ? "bg-blue-50" : ""}`}><span className={`text-[10px] font-semibold ${day === 24 ? "grid h-5 w-5 place-items-center rounded-full bg-blue-700 text-white" : "text-slate-600"}`}>{day}</span>{event && <div className="mt-2 rounded bg-blue-100 px-1.5 py-1 text-[9px] font-semibold text-blue-800">{event.title}</div>}</div>; })}</div></section><aside className="card soft-shadow p-5"><SectionHeader title="Próximos eventos" /><div className="space-y-4">{events.map((e) => <div key={e.title} className="flex gap-3"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-md bg-slate-100 text-xs font-bold">{String(e.day).padStart(2, "0")}</div><div><p className="text-xs font-bold">{e.title}</p><div className="mt-1"><StatusBadge tone={e.tone as Tone}>{e.type}</StatusBadge></div></div></div>)}</div></aside></div></div>;
}

function RecordsPage() {
  const records = [{ date: "18/09/2026", category: "Orientação", text: "Conversa sobre organização da rotina de estudos e entregas.", author: "Fernanda Oliveira", status: "Concluída", tone: "info" }, { date: "02/09/2026", category: "Elogio", text: "Participação destacada no projeto interdisciplinar de Ciências.", author: "Beatriz Santos", status: "Compartilhado", tone: "success" }, { date: "19/08/2026", category: "Pedagógica", text: "Atividade de Português entregue após o prazo combinado.", author: "Juliana Costa", status: "Acompanhada", tone: "warning" }];
  return <div className="page-enter"><PageHeader eyebrow="Acompanhamento" title="Registro escolar" description="Um histórico construtivo de orientações, conquistas e ocorrências." /><div className="mb-4 grid gap-3 sm:grid-cols-3"><StatCard label="Elogios" value="4" detail="Neste ano letivo" icon={CheckCircle2} tone="success" /><StatCard label="Orientações" value="2" detail="Todas acompanhadas" icon={Info} tone="info" /><StatCard label="Ocorrências" value="1" detail="Nenhuma em aberto" icon={HeartHandshake} tone="neutral" /></div><div className="space-y-3">{records.map((record) => <article key={record.date} className="card soft-shadow p-5"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><div className="flex items-center gap-2"><StatusBadge tone={record.tone as Tone}>{record.category}</StatusBadge><span className="text-[10px] text-slate-400">{record.date}</span></div><p className="mt-3 text-xs leading-5 text-slate-700">{record.text}</p><p className="mt-2 text-[10px] text-slate-500">Registrado por {record.author}</p></div><StatusBadge tone="success">{record.status}</StatusBadge></div></article>)}</div></div>;
}

function AnnouncementsPage() {
  return <div className="page-enter"><PageHeader eyebrow="Comunicação" title="Avisos da escola" description="Comunicados importantes do Colégio Modelo Horizonte." /><div className="grid gap-3 lg:grid-cols-2">{[{ t: "Reunião de responsáveis", d: "Encontro do 3º bimestre no dia 30/09, às 19h, no auditório.", p: "Importante", tone: "warning" }, { t: "Feira Cultural 2026", d: "As inscrições para apresentação de projetos ficam abertas até 05/10.", p: "Evento", tone: "info" }, { t: "Atualização do calendário", d: "O conselho de classe foi transferido para 16 de outubro.", p: "Calendário", tone: "neutral" }, { t: "Olimpíada de Matemática", d: "Parabéns aos estudantes classificados para a segunda fase.", p: "Conquista", tone: "success" }].map((a, i) => <article key={a.t} className="card soft-shadow p-5"><div className="flex items-start gap-4"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-md bg-blue-50"><Megaphone className="h-5 w-5 text-blue-700" /></div><div><div className="flex flex-wrap items-center gap-2"><h2 className="text-sm font-bold">{a.t}</h2><StatusBadge tone={a.tone as Tone}>{a.p}</StatusBadge></div><p className="mt-2 text-xs leading-5 text-slate-600">{a.d}</p><p className="mt-4 text-[10px] text-slate-400">{24 - i * 2}/09/2026 · Direção</p></div></div></article>)}</div></div>;
}

function ProfilePage() {
  return <div className="page-enter"><PageHeader eyebrow="Conta" title="Meu perfil" description="Seus dados acadêmicos e preferências de acesso." /><div className="grid gap-4 lg:grid-cols-[320px_1fr]"><section className="card soft-shadow p-6 text-center"><Avatar index={0} size="xl" className="mx-auto" /><h2 className="mt-4 text-lg font-bold">Lucas Silva</h2><p className="mt-1 text-xs text-slate-500">Aluno · 8º A</p><div className="mt-5 border-t pt-5 text-left text-xs"><p className="flex justify-between py-2"><span className="text-slate-500">Matrícula</span><strong>20261031</strong></p><p className="flex justify-between py-2"><span className="text-slate-500">Turno</span><strong>Manhã</strong></p><p className="flex justify-between py-2"><span className="text-slate-500">Ano letivo</span><strong>2026</strong></p></div></section><section className="card soft-shadow p-5"><SectionHeader title="Informações pessoais" description="Alterações cadastrais devem ser solicitadas à secretaria." /><div className="grid gap-4 sm:grid-cols-2">{[["Nome completo", "Lucas de Oliveira Silva"], ["Data de nascimento", "14/03/2012"], ["E-mail escolar", "lucas.silva@horizonte.edu.br"], ["Responsável", "Mariana Silva"], ["Telefone", "(11) 98765-4321"], ["Turma", "8º A · Ensino Fundamental"]].map(([l, v]) => <label key={l}><span className="mb-1.5 block text-[10px] font-semibold text-slate-500">{l}</span><input readOnly value={v} className="h-10 w-full rounded-md border border-slate-200 bg-slate-50 px-3 text-xs text-slate-700" /></label>)}</div></section></div></div>;
}

function ParentPage({ page }: { page: string }) {
  if (page === "alertas") return <AlertsPage />;
  if (page === "familia") return <FamilyCenter />;
  if (page === "notas") return <GradesPage />;
  if (page === "frequencia") return <AttendancePage />;
  if (page === "atividades") return <ActivitiesPage />;
  if (page === "avaliacoes") return <AssessmentsPage />;
  if (page === "calendario") return <CalendarPage />;
  return <GenericDocuments />;
}

function AlertsPage() {
  const [read, setRead] = useState<number[]>([]);
  const alerts = [{ date: "Hoje", title: "Falta registrada", detail: "Lucas faltou à aula de Matemática.", tone: "warning" }, { date: "Ontem", title: "Nova nota publicada", detail: "História · Nota 9,0.", tone: "success" }, { date: "23 SET", title: "Nova atividade de Ciências", detail: "Entrega prevista para 28 de setembro.", tone: "info" }, { date: "20 SET", title: "Orientação registrada", detail: "A coordenação publicou uma nova orientação.", tone: "neutral" }];
  return <div className="page-enter"><PageHeader eyebrow="Acompanhamento de Lucas" title="Central de alertas" description="Tudo que mudou na vida escolar, organizado em uma linha do tempo." action={<Button variant="secondary" icon={Check} onClick={() => setRead(alerts.map((_, i) => i))}>Marcar tudo como lido</Button>} /><section className="card soft-shadow p-5 md:p-7"><div className="mx-auto max-w-3xl">{alerts.map((alert, index) => <button key={alert.title} onClick={() => setRead((old) => old.includes(index) ? old : [...old, index])} className="group relative flex w-full gap-5 pb-8 text-left last:pb-0"><div className="w-14 shrink-0 pt-0.5 text-right text-[10px] font-bold text-slate-400">{alert.date}</div><div className="relative"><span className={`block h-3 w-3 rounded-full border-2 border-white ring-2 ${read.includes(index) ? "bg-slate-300 ring-slate-200" : "bg-blue-600 ring-blue-100"}`} />{index < alerts.length - 1 && <span className="absolute left-[5px] top-4 h-[calc(100%+18px)] w-px bg-slate-200" />}</div><div className={`-mt-1 flex-1 rounded-lg border p-4 transition group-hover:border-blue-200 ${read.includes(index) ? "bg-white" : "border-blue-100 bg-blue-50/50"}`}><div className="flex items-center justify-between"><p className="text-xs font-bold">{alert.title}</p>{!read.includes(index) && <span className="text-[9px] font-bold uppercase text-blue-700">Novo</span>}</div><p className="mt-1.5 text-xs text-slate-600">{alert.detail}</p></div></button>)}</div></section></div>;
}

function FamilyCenter() {
  return <div className="page-enter"><PageHeader eyebrow="Escola e família" title="Central da Família" description="Um espaço único para comunicados, reuniões, solicitações e documentos." action={<Button icon={Plus}>Nova solicitação</Button>} /><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{[{ icon: Megaphone, t: "Comunicados", n: "4 novos", d: "Avisos gerais da escola" }, { icon: CalendarDays, t: "Reuniões", n: "1 agendada", d: "Encontros com professores" }, { icon: MessageSquareText, t: "Solicitações", n: "2 abertas", d: "Atendimento e acompanhamento" }, { icon: FileText, t: "Documentos", n: "6 arquivos", d: "Declarações e autorizações" }, { icon: HeartHandshake, t: "Registros", n: "1 recente", d: "Orientações e ocorrências" }, { icon: UsersRound, t: "Convocações", n: "Nenhuma", d: "Chamados da coordenação" }].map(({ icon: Icon, t, n, d }) => <button key={t} className="card soft-shadow flex items-center gap-4 p-5 text-left transition hover:border-blue-200"><div className="grid h-11 w-11 place-items-center rounded-md bg-blue-50"><Icon className="h-5 w-5 text-blue-700" /></div><div className="flex-1"><p className="text-sm font-bold">{t}</p><p className="mt-1 text-[11px] text-slate-500">{d}</p></div><div className="text-right"><p className="text-[10px] font-semibold text-blue-700">{n}</p><ChevronRight className="ml-auto mt-1 h-4 w-4 text-slate-300" /></div></button>)}</div></div>;
}

function GenericDocuments() {
  return <div className="page-enter"><PageHeader eyebrow="Central da Família" title="Documentos" description="Arquivos compartilhados pela escola e solicitações recentes." /><div className="grid gap-3 md:grid-cols-2">{["Declaração de matrícula", "Calendário letivo 2026", "Autorização para passeio", "Regimento escolar"].map((name, i) => <article key={name} className="card flex items-center gap-4 p-4"><div className="grid h-10 w-10 place-items-center rounded-md bg-red-50"><FileText className="h-5 w-5 text-red-600" /></div><div className="flex-1"><p className="text-xs font-bold">{name}</p><p className="mt-1 text-[10px] text-slate-500">PDF · Atualizado em {20 - i}/09/2026</p></div><button className="grid h-9 w-9 place-items-center rounded-md border"><Download className="h-4 w-4" /></button></article>)}</div></div>;
}

function TeacherPage({ page, id }: { page: string; id?: string }) {
  if (page === "turmas") return id ? <ClassDetailPage /> : <ClassesPage />;
  if (page === "chamada") return <RollCallPage />;
  if (page === "notas") return <GradeEntryPage />;
  if (page === "planejamento") return <LessonPlanningPage />;
  if (page === "conteudo" || page === "diario") return <LessonJournalPage />;
  if (page === "avaliacoes") return <CreateAssessmentPage />;
  if (page === "atividades") return <TeacherActivitiesPage />;
  if (page === "materiais") return <TeacherMaterialsPage />;
  if (page === "calendario") return <CalendarPage />;
  return <TeacherReportsPage />;
}

function ClassesPage() {
  return <div className="page-enter"><PageHeader eyebrow="Professor" title="Minhas turmas" description="Acesse alunos, desempenho, frequência e registros de cada turma." /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{classes.map((item, index) => <Link href={`/professor/turmas/${index + 1}`} key={item.name} className="card soft-shadow group p-5 transition hover:border-blue-200"><div className="flex items-center justify-between"><div className="grid h-11 w-11 place-items-center rounded-md bg-blue-50"><UsersRound className="h-5 w-5 text-blue-700" /></div><ChevronRight className="h-5 w-5 text-slate-300 group-hover:text-blue-700" /></div><h2 className="mt-5 text-xl font-bold">{item.name}</h2><p className="mt-1 text-xs text-slate-500">{item.subject} · {item.room}</p><div className="mt-5 grid grid-cols-3 gap-2 border-t pt-4 text-center"><div><strong className="block text-sm">{item.students}</strong><span className="text-[9px] text-slate-400">Alunos</span></div><div><strong className="block text-sm">{item.average.toFixed(1).replace(".", ",")}</strong><span className="text-[9px] text-slate-400">Média</span></div><div><strong className="block text-sm">{item.attendance}%</strong><span className="text-[9px] text-slate-400">Frequência</span></div></div></Link>)}</div></div>;
}

function ClassDetailPage() {
  const list = students.filter((s) => s.className === "8º A").slice(0, 12);
  return <div className="page-enter"><PageHeader eyebrow="Minhas turmas / 8º A" title="Matemática · 8º A" description="32 alunos · Sala 12 · Segunda, quarta e quinta" action={<div className="flex gap-2"><Link href="/professor/chamada"><Button icon={UserCheck} variant="secondary">Chamada</Button></Link><Link href="/professor/notas"><Button icon={BookOpen}>Lançar notas</Button></Link></div>} /><div className="mb-4 grid grid-cols-2 gap-3 lg:grid-cols-4"><StatCard label="Alunos" value="32" detail="31 ativos" icon={UsersRound} /><StatCard label="Média da turma" value="7,8" detail="+0,3 no bimestre" icon={TrendingUp} tone="success" /><StatCard label="Frequência" value="93%" detail="Dentro da meta" icon={UserCheck} tone="success" /><StatCard label="Em atenção" value="3" detail="Acompanhamento indicado" icon={AlertTriangle} tone="warning" /></div><section className="card soft-shadow overflow-hidden"><div className="p-4"><div className="flex h-9 max-w-sm items-center gap-2 rounded-md border px-3"><Search className="h-4 w-4 text-slate-400" /><input placeholder="Buscar aluno..." className="w-full text-xs outline-none" /></div></div><div className="table-wrap"><table className="data-table"><thead><tr><th>Aluno</th><th>Matrícula</th><th>Frequência</th><th>Média</th><th>Situação</th></tr></thead><tbody>{list.map((student, i) => <tr key={student.id}><td><div className="flex items-center gap-3"><Avatar index={i === 0 ? 0 : i % 6} size="sm" /><span className="font-semibold">{student.name}</span></div></td><td>{student.registration}</td><td>{student.attendance}%</td><td>{student.average.toFixed(1).replace(".", ",")}</td><td><StatusBadge tone={student.average < 6 || student.attendance < 80 ? "warning" : "success"}>{student.average < 6 || student.attendance < 80 ? "Atenção" : "Adequada"}</StatusBadge></td></tr>)}</tbody></table></div></section></div>;
}

type AttendanceStatus = "Presente" | "Falta" | "Justificada" | "Atrasado";
function RollCallPage() {
  const list = students.filter((s) => s.className === "8º A").slice(0, 12);
  const [status, setStatus] = useState<Record<string, AttendanceStatus>>(Object.fromEntries(list.map((s) => [s.id, "Presente"])));
  const [toast, setToast] = useState(false);
  const setAll = () => setStatus(Object.fromEntries(list.map((s) => [s.id, "Presente"])));
  return <div className="page-enter"><PageHeader eyebrow="Diário de classe" title="Chamada" description="Registre a frequência da turma de forma rápida." /><Toolbar><Select label="Turma"><option>8º A</option><option>8º B</option><option>9º A</option></Select><Select label="Disciplina"><option>Matemática</option></Select><label><span className="mb-1.5 block text-[10px] font-semibold text-slate-500">Data</span><input type="date" defaultValue="2026-09-24" className="h-9 rounded-md border border-slate-200 px-3 text-xs" /></label><Select label="Horário"><option>08:00</option><option>10:20</option></Select><div className="ml-auto self-end"><Button variant="secondary" icon={Check} onClick={setAll}>Marcar todos presentes</Button></div></Toolbar><section className="card soft-shadow overflow-hidden"><div className="border-b p-4"><div className="flex flex-wrap gap-4 text-[11px]"><span><strong className="text-emerald-700">{Object.values(status).filter((s) => s === "Presente").length}</strong> presentes</span><span><strong className="text-red-700">{Object.values(status).filter((s) => s === "Falta").length}</strong> faltas</span><span><strong className="text-amber-700">{Object.values(status).filter((s) => s === "Atrasado").length}</strong> atrasos</span></div></div><div className="divide-y divide-slate-100">{list.map((student, index) => <div key={student.id} className="flex flex-col gap-3 p-3 sm:flex-row sm:items-center"><div className="flex min-w-56 flex-1 items-center gap-3"><Avatar index={index === 0 ? 0 : index % 6} size="sm" /><div><p className="text-xs font-bold">{student.name}</p><p className="text-[10px] text-slate-400">{student.registration}</p></div></div><div className="grid grid-cols-2 gap-1.5 sm:flex">{(["Presente", "Falta", "Justificada", "Atrasado"] as AttendanceStatus[]).map((value) => <button key={value} onClick={() => setStatus((old) => ({ ...old, [student.id]: value }))} className={`h-8 rounded-md border px-3 text-[10px] font-semibold transition ${status[student.id] === value ? value === "Presente" ? "border-emerald-600 bg-emerald-600 text-white" : value === "Falta" ? "border-red-600 bg-red-600 text-white" : "border-amber-500 bg-amber-500 text-white" : "border-slate-200 bg-white text-slate-500 hover:bg-slate-50"}`}>{value}</button>)}</div></div>)}</div><div className="flex justify-end border-t bg-slate-50 p-4"><Button icon={Save} onClick={() => setToast(true)}>Salvar chamada</Button></div></section>{toast && <DemoToast message="Chamada da turma 8º A salva com sucesso." onClose={() => setToast(false)} />}</div>;
}

function GradeEntryPage() {
  const list = students.filter((s) => s.className === "8º A").slice(0, 12);
  const [grades, setGrades] = useState<Record<string, string>>(Object.fromEntries(list.map((s, i) => [s.id, i < 7 ? (6.5 + (i % 4) * .8).toFixed(1) : ""])));
  const [toast, setToast] = useState(false);
  const invalid = Object.values(grades).some((g) => g !== "" && (Number(g) < 0 || Number(g) > 10));
  const filled = Object.values(grades).filter(Boolean).map(Number);
  const average = filled.length ? filled.reduce((a, b) => a + b, 0) / filled.length : 0;
  return <div className="page-enter"><PageHeader eyebrow="Diário de classe" title="Lançamento de notas" description="Insira notas de 0 a 10. A média da turma é atualizada automaticamente." /><Toolbar><Select label="Turma"><option>8º A</option><option>8º B</option></Select><Select label="Disciplina"><option>Matemática</option></Select><Select label="Bimestre"><option>3º bimestre</option></Select><Select label="Avaliação"><option>Prova bimestral</option><option>Lista de exercícios</option></Select><div className="ml-auto self-end"><StatusBadge tone={average >= 7 ? "success" : "warning"}>Média da turma: {average.toFixed(1).replace(".", ",")}</StatusBadge></div></Toolbar>{invalid && <div className="mb-4 flex items-center gap-2 rounded-md border border-red-200 bg-red-50 p-3 text-xs text-red-700"><AlertTriangle className="h-4 w-4" />Existem notas fora do intervalo permitido (0 a 10).</div>}<section className="card soft-shadow overflow-hidden"><div className="table-wrap"><table className="data-table"><thead><tr><th>Aluno</th><th>Matrícula</th><th>Nota</th><th>Observação</th><th>Situação</th></tr></thead><tbody>{list.map((student, i) => { const grade = Number(grades[student.id]); return <tr key={student.id}><td><div className="flex items-center gap-2"><Avatar index={i === 0 ? 0 : i % 6} size="sm" /><span className="font-semibold">{student.name}</span></div></td><td>{student.registration}</td><td><input aria-label={`Nota de ${student.name}`} type="number" min="0" max="10" step="0.1" value={grades[student.id]} onChange={(e) => setGrades((old) => ({ ...old, [student.id]: e.target.value }))} className={`h-9 w-20 rounded-md border px-2 text-center text-xs font-bold outline-none ${grades[student.id] && (grade < 0 || grade > 10) ? "border-red-400 bg-red-50" : "border-slate-200"}`} /></td><td><input aria-label={`Observação sobre ${student.name}`} placeholder="Adicionar observação" className="h-9 w-full min-w-48 rounded-md border border-slate-200 px-3 text-xs outline-none" /></td><td>{grades[student.id] ? <StatusBadge tone={grade >= 6 ? "success" : "warning"}>{grade >= 6 ? "Na média" : "Atenção"}</StatusBadge> : <StatusBadge>Lançar</StatusBadge>}</td></tr>; })}</tbody></table></div><div className="flex items-center justify-between border-t bg-slate-50 p-4"><p className="text-[10px] text-slate-500">{filled.length} de {list.length} notas preenchidas</p><Button icon={Save} disabled={invalid} onClick={() => setToast(true)}>Salvar notas</Button></div></section>{toast && <DemoToast message="Notas salvas no ambiente demonstrativo." onClose={() => setToast(false)} />}</div>;
}

function LessonPlanningPage() {
  const [toast, setToast] = useState(false);
  return <div className="page-enter"><PageHeader eyebrow="Organização pedagógica" title="Planejamento de aulas" description="Registre objetivos, metodologia e recursos para suas próximas aulas." action={<Button icon={Plus}>Novo planejamento</Button>} /><div className="grid gap-4 xl:grid-cols-[1fr_340px]"><form onSubmit={(e) => { e.preventDefault(); setToast(true); }} className="card soft-shadow p-5"><div className="grid gap-4 sm:grid-cols-3"><Field label="Data"><input type="date" defaultValue="2026-09-28" className="field" /></Field><Field label="Turma"><select className="field"><option>8º A</option><option>8º B</option><option>9º A</option></select></Field><Field label="Disciplina"><select className="field"><option>Matemática</option></select></Field></div><div className="mt-4 grid gap-4"><Field label="Objetivo da aula"><input className="field" defaultValue="Resolver equações de segundo grau usando diferentes estratégias" /></Field><Field label="Conteúdo"><textarea className="field min-h-20 py-3" defaultValue="Equações completas e incompletas; fórmula de Bhaskara; interpretação geométrica." /></Field><Field label="Metodologia"><textarea className="field min-h-20 py-3" defaultValue="Retomada dialogada, exemplos guiados, resolução em duplas e correção coletiva." /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Recursos"><input className="field" defaultValue="Quadro, slides e lista de exercícios" /></Field><Field label="Observações"><input className="field" placeholder="Opcional" /></Field></div></div><div className="mt-5 flex justify-end"><Button type="submit" icon={Save}>Salvar planejamento</Button></div></form><aside className="card soft-shadow p-5"><SectionHeader title="Próximos planejamentos" /><div className="space-y-3">{[["28 SET", "8º A", "Equações do 2º grau"], ["29 SET", "9º A", "Funções quadráticas"], ["30 SET", "8º B", "Revisão bimestral"]].map((p) => <div key={p[0]} className="rounded-md border p-3"><span className="text-[10px] font-bold text-blue-700">{p[0]}</span><p className="mt-1 text-xs font-bold">{p[1]} · Matemática</p><p className="mt-1 text-[11px] text-slate-500">{p[2]}</p></div>)}</div></aside></div>{toast && <DemoToast message="Planejamento salvo com sucesso." onClose={() => setToast(false)} />}</div>;
}

function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label><span className="mb-1.5 block text-[10px] font-semibold text-slate-500">{label}</span>{children}</label>; }

function LessonJournalPage() {
  return <div className="page-enter"><PageHeader eyebrow="Diário digital" title="Conteúdo ministrado" description="Histórico das aulas e conteúdos registrados." action={<Button icon={Plus}>Registrar conteúdo</Button>} /><section className="card soft-shadow overflow-hidden"><div className="table-wrap"><table className="data-table"><thead><tr><th>Data</th><th>Turma</th><th>Disciplina</th><th>Conteúdo</th><th>Professor</th><th>Status</th></tr></thead><tbody>{[["24/09/2026", "8º A", "Matemática", "Equações do segundo grau"], ["23/09/2026", "9º A", "Matemática", "Função quadrática e gráficos"], ["22/09/2026", "8º B", "Matemática", "Produtos notáveis"], ["21/09/2026", "8º A", "Matemática", "Revisão de fatoração"]].map((r) => <tr key={`${r[0]}${r[1]}`}><td>{r[0]}</td><td className="font-semibold">{r[1]}</td><td>{r[2]}</td><td>{r[3]}</td><td>Rafael Almeida</td><td><StatusBadge tone="success">Registrado</StatusBadge></td></tr>)}</tbody></table></div></section></div>;
}

function CreateAssessmentPage() {
  const [toast, setToast] = useState(false);
  return <div className="page-enter"><PageHeader eyebrow="Avaliações" title="Planejamento de avaliações" description="Crie instrumentos avaliativos e acompanhe o calendário das turmas." action={<Button icon={Plus}>Nova avaliação</Button>} /><div className="grid gap-4 xl:grid-cols-[.9fr_1.1fr]"><form onSubmit={(e) => { e.preventDefault(); setToast(true); }} className="card soft-shadow p-5"><SectionHeader title="Cadastrar avaliação" /><div className="grid gap-4 sm:grid-cols-2"><Field label="Nome"><input required className="field" placeholder="Ex.: Prova bimestral" /></Field><Field label="Tipo"><select className="field"><option>Prova</option><option>Trabalho</option><option>Atividade</option><option>Simulado</option><option>Projeto</option></select></Field><Field label="Data"><input type="date" className="field" defaultValue="2026-10-02" /></Field><Field label="Valor"><input type="number" min="0" max="10" className="field" defaultValue="10" /></Field><Field label="Turma"><select className="field"><option>8º A</option><option>8º B</option><option>9º A</option></select></Field><Field label="Disciplina"><select className="field"><option>Matemática</option></select></Field></div><div className="mt-4"><Field label="Conteúdo"><textarea className="field min-h-20 py-3" placeholder="Conteúdos que serão avaliados" /></Field></div><div className="mt-4"><Field label="Descrição"><textarea className="field min-h-20 py-3" placeholder="Orientações para os alunos" /></Field></div><div className="mt-5 flex justify-end"><Button icon={Save} type="submit">Salvar avaliação</Button></div></form><section className="card soft-shadow p-5"><SectionHeader title="Avaliações programadas" /><div className="space-y-3">{assessments.map((a) => <div key={a.subject} className="flex items-center gap-4 rounded-md border p-4"><div className="grid h-11 w-11 place-items-center rounded-md bg-blue-50 text-center text-[10px] font-bold text-blue-700">{a.date}</div><div className="flex-1"><p className="text-xs font-bold">{a.title}</p><p className="mt-1 text-[11px] text-slate-500">{a.subject} · 8º A · {a.content}</p></div><StatusBadge tone="info">Programada</StatusBadge></div>)}</div></section></div>{toast && <DemoToast message="Avaliação criada e adicionada ao calendário." onClose={() => setToast(false)} />}</div>;
}

function TeacherActivitiesPage() {
  return <div className="page-enter"><PageHeader eyebrow="Aprendizagem" title="Atividades" description="Publique atividades e acompanhe entregas e correções." action={<Button icon={Plus}>Nova atividade</Button>} /><div className="mb-4 grid grid-cols-2 gap-3 lg:grid-cols-4"><StatCard label="Publicadas" value="12" detail="Neste bimestre" icon={ListTodo} /><StatCard label="Para corrigir" value="18" detail="2 atividades" icon={BookOpen} tone="warning" /><StatCard label="Corrigidas" value="146" detail="94% das entregas" icon={CheckCircle2} tone="success" /><StatCard label="Atrasadas" value="9" detail="Entre 3 turmas" icon={AlertTriangle} tone="danger" /></div><section className="card soft-shadow overflow-hidden"><div className="table-wrap"><table className="data-table"><thead><tr><th>Atividade</th><th>Turma</th><th>Prazo</th><th>Entregas</th><th>Correções</th><th>Situação</th></tr></thead><tbody>{activities.map((a, i) => <tr key={a.title}><td><p className="font-semibold">{a.title}</p><p className="text-[10px] text-slate-400">{a.subject}</p></td><td>{classes[i % 3].name}</td><td>{a.due}</td><td>{[28, 25, 31, 27][i]}/{classes[i % 3].students}</td><td><ProgressBar value={[56, 88, 100, 34][i]} /></td><td><StatusBadge tone={i === 2 ? "success" : "warning"}>{i === 2 ? "Concluída" : "Em andamento"}</StatusBadge></td></tr>)}</tbody></table></div></section></div>;
}

function TeacherMaterialsPage() {
  return <MaterialsPage />;
}

function TeacherReportsPage() {
  return <div className="page-enter"><PageHeader eyebrow="Análise" title="Relatórios" description="Indicadores consolidados das suas turmas e atividades." /><div className="grid gap-4 xl:grid-cols-2"><section className="card soft-shadow p-5"><SectionHeader title="Evolução das turmas" /><SchoolTrendChart dataKey="media" /></section><section className="card soft-shadow p-5"><SectionHeader title="Frequência média" /><SchoolTrendChart /></section></div></div>;
}

function CoordinatorPage({ page, id }: { page: string; id?: string }) {
  if (page === "acompanhamento") return <TrackingPage />;
  if (page === "alunos") return id ? <StudentProfilePage id={id} /> : <StudentDirectory basePath="/coordenacao" />;
  if (page === "professores") return <TeacherMonitoringPage />;
  if (page === "turmas") return <SchoolClassesPage title="Acompanhamento das turmas" />;
  if (page === "ocorrencias") return <RecordsManagementPage />;
  if (page === "avisos") return <AnnouncementManagementPage />;
  if (page === "calendario") return <CalendarPage />;
  return <CoordinatorReports />;
}

function TrackingPage() {
  const [classFilter, setClassFilter] = useState("Todas");
  const [situation, setSituation] = useState("Todos");
  const tracked = useMemo(() => students.filter((s) => (s.average < 6 || s.attendance < 80 || s.occurrences >= 3 || s.lateActivities >= 3) && (classFilter === "Todas" || s.className === classFilter) && (situation === "Todos" || (situation === "Crítico" ? s.average < 5.5 || s.attendance < 75 : !(s.average < 5.5 || s.attendance < 75)))), [classFilter, situation]);
  return <div className="page-enter"><PageHeader eyebrow="Central pedagógica" title="Acompanhamento Acadêmico" description="Alunos identificados automaticamente pelos critérios de média, frequência, ocorrências e atividades." /><div className="mb-4 grid grid-cols-2 gap-3 lg:grid-cols-4"><StatCard label="Em acompanhamento" value={String(tracked.length)} detail="Todos os critérios" icon={Activity} tone="warning" /><StatCard label="Média abaixo de 6" value={String(students.filter((s) => s.average < 6).length)} detail="Prioridade acadêmica" icon={TrendingUp} tone="danger" /><StatCard label="Frequência abaixo de 80%" value={String(students.filter((s) => s.attendance < 80).length)} detail="Risco de reprovação" icon={UserCheck} tone="warning" /><StatCard label="3+ ocorrências" value={String(students.filter((s) => s.occurrences >= 3).length)} detail="Acompanhamento ativo" icon={HeartHandshake} tone="neutral" /></div><Toolbar><Select label="Turma" value={classFilter} onChange={setClassFilter}><option>Todas</option><option>8º A</option><option>8º B</option><option>9º A</option></Select><Select label="Série"><option>Todas</option><option>8º ano</option><option>9º ano</option></Select><Select label="Turno"><option>Todos</option><option>Manhã</option></Select><Select label="Situação" value={situation} onChange={setSituation}><option>Todos</option><option>Crítico</option><option>Atenção</option></Select><span className="ml-auto self-end pb-2 text-[10px] text-slate-500">{tracked.length} resultados</span></Toolbar><section className="card soft-shadow overflow-hidden"><div className="table-wrap"><table className="data-table"><thead><tr><th>Aluno</th><th>Turma</th><th>Média</th><th>Frequência</th><th>Ocorrências</th><th>Atrasadas</th><th>Situação</th></tr></thead><tbody>{tracked.map((s, i) => <tr key={s.id}><td><Link href={`/coordenacao/alunos/${s.id}`} className="flex items-center gap-2 font-semibold hover:text-blue-700"><Avatar index={i % 6} size="sm" />{s.name}</Link></td><td>{s.className}</td><td>{s.average.toFixed(1).replace(".", ",")}</td><td>{s.attendance}%</td><td>{s.occurrences}</td><td>{s.lateActivities}</td><td><StatusBadge tone={s.average < 5.5 || s.attendance < 75 ? "danger" : "warning"}>{s.average < 5.5 || s.attendance < 75 ? "Crítico" : "Atenção"}</StatusBadge></td></tr>)}</tbody></table></div></section></div>;
}

function StudentDirectory({ basePath }: { basePath: "/coordenacao" | "/direcao" }) {
  const [query, setQuery] = useState("");
  const visible = students.filter((s) => s.name.toLowerCase().includes(query.toLowerCase()));
  return <div className="page-enter"><PageHeader eyebrow="Coordenação" title="Alunos" description="30 alunos demonstrativos distribuídos em três turmas." /><Toolbar><label className="flex h-9 min-w-60 flex-1 items-center gap-2 rounded-md border px-3"><Search className="h-4 w-4 text-slate-400" /><input value={query} onChange={(e) => setQuery(e.target.value)} className="w-full text-xs outline-none" placeholder="Buscar por nome..." /></label><Select label="Turma"><option>Todas</option><option>8º A</option><option>8º B</option><option>9º A</option></Select></Toolbar><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{visible.map((s, i) => <Link href={`${basePath}/alunos/${s.id}`} key={s.id} className="card soft-shadow flex items-center gap-3 p-4 hover:border-blue-200"><Avatar index={i % 6} /><div className="min-w-0 flex-1"><p className="truncate text-xs font-bold">{s.name}</p><p className="mt-1 text-[10px] text-slate-500">{s.className} · {s.registration}</p><div className="mt-2 flex gap-3 text-[10px]"><span>Média <strong>{s.average.toFixed(1).replace(".", ",")}</strong></span><span>Freq. <strong>{s.attendance}%</strong></span></div></div><ChevronRight className="h-4 w-4 text-slate-300" /></Link>)}</div></div>;
}

function StudentProfilePage({ id }: { id: string }) {
  const student = students.find((s) => s.id === id) ?? students[0];
  const [tab, setTab] = useState("Visão geral");
  const tabs = ["Visão geral", "Notas", "Frequência", "Ocorrências", "Atividades", "Histórico", "Observações"];
  return <div className="page-enter"><div className="mb-5 flex flex-col gap-4 rounded-lg border bg-white p-5 sm:flex-row sm:items-center"><Avatar index={student.id === "lucas-silva" ? 0 : 5} size="xl" /><div className="flex-1"><p className="text-[10px] font-bold uppercase text-blue-700">Ficha do aluno</p><h1 className="mt-1 text-2xl font-bold">{student.name}</h1><p className="mt-1 text-xs text-slate-500">{student.className} · Matrícula {student.registration} · Turno da manhã</p><div className="mt-3 flex flex-wrap gap-2"><StatusBadge tone={student.average < 6 ? "warning" : "success"}>{student.average < 6 ? "Em acompanhamento" : "Situação adequada"}</StatusBadge><StatusBadge tone="info">Responsável: Mariana Silva</StatusBadge></div></div><Button variant="secondary" icon={MessageSquareText}>Registrar observação</Button></div><div className="mobile-scroll mb-4 flex gap-1 overflow-x-auto rounded-lg border bg-white p-1.5">{tabs.map((item) => <button key={item} onClick={() => setTab(item)} className={`h-9 whitespace-nowrap rounded-md px-3 text-xs font-semibold ${tab === item ? "bg-blue-700 text-white" : "text-slate-500 hover:bg-slate-50"}`}>{item}</button>)}</div>{tab === "Visão geral" ? <div className="grid gap-4 xl:grid-cols-[1.2fr_.8fr]"><div><div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><StatCard label="Média geral" value={student.average.toFixed(1).replace(".", ",")} detail="Meta: 7,0" icon={TrendingUp} tone={student.average < 6 ? "danger" : "success"} /><StatCard label="Frequência" value={`${student.attendance}%`} detail="Meta: 80%" icon={UserCheck} tone={student.attendance < 80 ? "danger" : "success"} /><StatCard label="Ocorrências" value={String(student.occurrences)} detail="No ano letivo" icon={HeartHandshake} tone={student.occurrences >= 3 ? "warning" : "neutral"} /><StatCard label="Atrasadas" value={String(student.lateActivities)} detail="Atividades" icon={ListTodo} tone={student.lateActivities >= 3 ? "warning" : "info"} /></div><section className="card soft-shadow mt-4 p-5"><SectionHeader title="Evolução acadêmica" /><PerformanceChart /></section></div><aside className="card soft-shadow p-5"><SectionHeader title="Linha do tempo escolar" /><div className="space-y-5">{[["Hoje", "Nova nota publicada", "História · 9,0"], ["20 SET", "Orientação pedagógica", "Rotina de estudos"], ["12 SET", "Elogio registrado", "Projeto de Ciências"], ["02 SET", "Atividade entregue", "Matemática"]].map((e, i) => <div key={e[0]} className="flex gap-3"><div className="relative"><span className="block h-2.5 w-2.5 rounded-full bg-blue-600" />{i < 3 && <span className="absolute left-[4px] top-3 h-10 w-px bg-slate-200" />}</div><div><p className="text-[10px] font-bold text-slate-400">{e[0]}</p><p className="mt-1 text-xs font-semibold">{e[1]}</p><p className="mt-1 text-[11px] text-slate-500">{e[2]}</p></div></div>)}</div><div className="mt-6 border-t pt-5 text-xs"><p className="flex justify-between py-1.5"><span className="text-slate-500">Responsável</span><strong>Mariana Silva</strong></p><p className="flex justify-between py-1.5"><span className="text-slate-500">Contato</span><strong>(11) 98765-4321</strong></p></div></aside></div> : <ProfileTab tab={tab} />}</div>;
}

function ProfileTab({ tab }: { tab: string }) {
  if (tab === "Notas") return <GradesPage />;
  if (tab === "Frequência") return <AttendancePage />;
  if (tab === "Ocorrências") return <RecordsPage />;
  if (tab === "Atividades") return <ActivitiesPage />;
  return <section className="card soft-shadow p-5"><SectionHeader title={tab} description="Registros organizados em ordem cronológica." /><div className="space-y-3">{[1, 2, 3].map((i) => <div key={i} className="rounded-md border p-4"><div className="flex justify-between"><p className="text-xs font-bold">Registro pedagógico {i}</p><span className="text-[10px] text-slate-400">{24 - i}/09/2026</span></div><p className="mt-2 text-xs text-slate-500">Informação demonstrativa para acompanhamento da equipe pedagógica.</p></div>)}</div></section>;
}

function TeacherMonitoringPage() {
  const teachers = [{ name: "Rafael Almeida", subject: "Matemática", classes: 3, diary: 96, grades: 100, attendance: 98, plans: 92 }, { name: "Juliana Costa", subject: "Português", classes: 5, diary: 100, grades: 94, attendance: 100, plans: 100 }, { name: "Paulo Mendes", subject: "História", classes: 4, diary: 88, grades: 92, attendance: 96, plans: 85 }, { name: "Camila Rocha", subject: "Geografia", classes: 4, diary: 94, grades: 100, attendance: 98, plans: 90 }, { name: "Beatriz Santos", subject: "Ciências", classes: 5, diary: 97, grades: 96, attendance: 99, plans: 96 }];
  return <div className="page-enter"><PageHeader eyebrow="Acompanhamento administrativo" title="Monitoramento de professores" description="Andamento das obrigações pedagógicas, sem comparação ou ranking." /><section className="card soft-shadow overflow-hidden"><div className="table-wrap"><table className="data-table"><thead><tr><th>Professor</th><th>Turmas</th><th>Diários</th><th>Notas lançadas</th><th>Frequência</th><th>Planejamentos</th><th>Situação</th></tr></thead><tbody>{teachers.map((t, i) => <tr key={t.name}><td><div className="flex items-center gap-2"><Avatar index={i === 0 ? 2 : (i + 1) % 6} size="sm" /><div><p className="font-semibold">{t.name}</p><p className="text-[10px] text-slate-400">{t.subject}</p></div></div></td><td>{t.classes}</td><td><ProgressBar value={t.diary} /></td><td><ProgressBar value={t.grades} tone={t.grades < 95 ? "warning" : "success"} /></td><td><ProgressBar value={t.attendance} tone="success" /></td><td><ProgressBar value={t.plans} tone={t.plans < 90 ? "warning" : "info"} /></td><td><StatusBadge tone={Math.min(t.diary, t.grades, t.attendance, t.plans) < 90 ? "warning" : "success"}>{Math.min(t.diary, t.grades, t.attendance, t.plans) < 90 ? "Pendências" : "Em dia"}</StatusBadge></td></tr>)}</tbody></table></div></section></div>;
}

function SchoolClassesPage({ title }: { title: string }) {
  return <div className="page-enter"><PageHeader eyebrow="Gestão de turmas" title={title} description="Indicadores acadêmicos e de frequência das turmas." /><div className="grid gap-4 md:grid-cols-3">{classes.map((c, i) => <article key={c.name} className="card soft-shadow p-5"><div className="flex items-center justify-between"><div><h2 className="text-xl font-bold">{c.name}</h2><p className="mt-1 text-xs text-slate-500">{c.students} alunos · Manhã</p></div><StatusBadge tone={c.average >= 7.5 ? "success" : "warning"}>{c.average >= 7.5 ? "Adequada" : "Acompanhar"}</StatusBadge></div><div className="mt-5 space-y-4"><ProgressBar value={c.average * 10} label={`Média ${c.average.toFixed(1).replace(".", ",")}`} tone={c.average >= 7.5 ? "success" : "warning"} /><ProgressBar value={c.attendance} label={`Frequência ${c.attendance}%`} tone={c.attendance >= 90 ? "success" : "warning"} /></div><div className="mt-5 flex justify-between border-t pt-4 text-[11px]"><span className="text-slate-500">Ocorrências</span><strong>{[1, 4, 0][i]}</strong></div></article>)}</div></div>;
}

function RecordsManagementPage() {
  return <RecordsPage />;
}

function AnnouncementManagementPage() {
  const [toast, setToast] = useState(false);
  return <div className="page-enter"><PageHeader eyebrow="Comunicação escolar" title="Gestão de avisos" description="Publique comunicados segmentados para a comunidade escolar." /><div className="grid gap-4 xl:grid-cols-[.85fr_1.15fr]"><form onSubmit={(e) => { e.preventDefault(); setToast(true); }} className="card soft-shadow p-5"><SectionHeader title="Novo aviso" /><div className="space-y-4"><Field label="Título"><input required className="field" placeholder="Título do comunicado" /></Field><Field label="Descrição"><textarea required className="field min-h-24 py-3" placeholder="Escreva o comunicado" /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Categoria"><select className="field"><option>Comunicado</option><option>Evento</option><option>Acadêmico</option></select></Field><Field label="Destinatários"><select className="field"><option>Todos</option><option>Alunos</option><option>Responsáveis</option><option>Professores</option><option>Turma específica</option></select></Field><Field label="Data"><input type="date" className="field" defaultValue="2026-09-24" /></Field><Field label="Prioridade"><select className="field"><option>Normal</option><option>Importante</option><option>Urgente</option></select></Field></div><button type="button" className="flex h-20 w-full items-center justify-center gap-2 rounded-md border border-dashed text-xs text-slate-500"><Paperclip className="h-4 w-4" />Adicionar anexo</button><div className="flex justify-end"><Button type="submit" icon={Send}>Publicar aviso</Button></div></div></form><PublishedAnnouncements /></div>{toast && <DemoToast message="Aviso publicado para os destinatários selecionados." onClose={() => setToast(false)} />}</div>;
}

function PublishedAnnouncements() {
  const items = ["Reunião de responsáveis", "Feira Cultural 2026", "Atualização do calendário", "Olimpíada de Matemática"];
  return <section className="card soft-shadow p-5"><SectionHeader title="Avisos publicados" /><div className="space-y-3">{items.map((title, index) => <div key={title} className="flex items-center gap-3 rounded-md border p-4"><div className="grid h-9 w-9 place-items-center rounded-md bg-blue-50"><Megaphone className="h-4 w-4 text-blue-700" /></div><div className="flex-1"><p className="text-xs font-bold">{title}</p><p className="mt-1 text-[10px] text-slate-500">Publicado em {24 - index * 2}/09 · Todos os perfis</p></div><StatusBadge tone={index === 0 ? "warning" : "success"}>{index === 0 ? "Importante" : "Publicado"}</StatusBadge></div>)}</div></section>;
}

function CoordinatorReports() {
  return <div className="page-enter"><PageHeader eyebrow="Coordenação pedagógica" title="Relatórios" description="Visão consolidada de desempenho, frequência e acompanhamento." /><div className="grid gap-4 xl:grid-cols-2"><section className="card p-5"><SectionHeader title="Desempenho acadêmico" /><SchoolTrendChart dataKey="media" /></section><section className="card p-5"><SectionHeader title="Evolução da frequência" /><SchoolTrendChart /></section></div></div>;
}

function DirectorPage({ page, id }: { page: string; id?: string }) {
  if (page === "analytics") return <AnalyticsPage />;
  if (page === "turmas") return <SchoolClassesPage title="Visão das turmas" />;
  if (page === "alunos") return id ? <StudentProfilePage id={id} /> : <StudentDirectory basePath="/direcao" />;
  if (page === "professores") return <TeacherMonitoringPage />;
  if (page === "ocorrencias") return <RecordsManagementPage />;
  if (page === "avisos") return <AnnouncementManagementPage />;
  if (page === "calendario") return <CalendarPage />;
  return <ExecutiveReports />;
}

function AnalyticsPage() {
  const [metric, setMetric] = useState<"frequencia" | "media" | "ocorrencias">("frequencia");
  return <div className="page-enter"><PageHeader eyebrow="Inteligência escolar" title="Analytics" description="Indicadores estratégicos do Colégio Modelo Horizonte." action={<Select label="Período"><option>Ano letivo 2026</option><option>3º bimestre</option></Select>} /><div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><StatCard label="Alunos ativos" value="748" detail="97% de ocupação" icon={UsersRound} /><StatCard label="Média acadêmica" value="7,8" detail="+0,4 no período" icon={TrendingUp} tone="success" /><StatCard label="Frequência média" value="93%" detail="Meta superada" icon={UserCheck} tone="success" /><StatCard label="Registros no mês" value="8" detail="-22% vs. agosto" icon={HeartHandshake} tone="warning" /></div><div className="mt-4 grid gap-4 xl:grid-cols-[1.25fr_.75fr]"><section className="card soft-shadow p-5"><div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><SectionHeader title="Evolução dos indicadores" description="Visualize a tendência ao longo do ano" /><div className="flex gap-1 rounded-md bg-slate-100 p-1">{([['frequencia', 'Frequência'], ['media', 'Desempenho'], ['ocorrencias', 'Ocorrências']] as const).map(([key, label]) => <button key={key} onClick={() => setMetric(key)} className={`h-7 rounded px-2 text-[10px] font-semibold ${metric === key ? "bg-white text-blue-700 shadow-sm" : "text-slate-500"}`}>{label}</button>)}</div></div><SchoolTrendChart dataKey={metric} /></section><section className="card soft-shadow p-5"><SectionHeader title="Alunos por etapa" description="Distribuição das 748 matrículas" /><DistributionChart /></section></div><div className="mt-4 grid gap-4 xl:grid-cols-2"><section className="card soft-shadow p-5"><SectionHeader title="Desempenho por disciplina" description="Média geral da escola" /><SubjectChart /></section><section className="card soft-shadow p-5"><SectionHeader title="Atividades e entregas" /><div className="space-y-5">{[["Atividades publicadas", 86, "info"], ["Entregas no prazo", 91, "success"], ["Correções concluídas", 78, "warning"], ["Devolutivas publicadas", 84, "info"]].map(([label, value, tone]) => <ProgressBar key={String(label)} label={String(label)} value={Number(value)} tone={tone as Tone} />)}</div><div className="mt-6 grid grid-cols-3 gap-3 border-t pt-5 text-center"><div><strong className="block text-xl">384</strong><span className="text-[10px] text-slate-500">Publicadas</span></div><div><strong className="block text-xl">4.820</strong><span className="text-[10px] text-slate-500">Entregas</span></div><div><strong className="block text-xl">212</strong><span className="text-[10px] text-slate-500">Pendentes</span></div></div></section></div></div>;
}

function ExecutiveReports() {
  const [toast, setToast] = useState(false);
  return <div className="page-enter"><PageHeader eyebrow="Direção geral" title="Relatórios gerenciais" description="Exporte visões consolidadas para acompanhamento e tomada de decisão." /><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{[{ t: "Relatório acadêmico", d: "Médias e evolução por turma", icon: TrendingUp }, { t: "Relatório de frequência", d: "Presenças e faltas por período", icon: UserCheck }, { t: "Relatório de ocorrências", d: "Registros por categoria e turma", icon: HeartHandshake }, { t: "Relatório de atividades", d: "Publicações, entregas e correções", icon: ListTodo }, { t: "Panorama de professores", d: "Andamento das obrigações", icon: UsersRound }, { t: "Resumo executivo", d: "Todos os indicadores estratégicos", icon: FileText }].map(({ t, d, icon: Icon }) => <article key={t} className="card soft-shadow p-5"><div className="flex items-start justify-between"><div className="grid h-10 w-10 place-items-center rounded-md bg-blue-50"><Icon className="h-5 w-5 text-blue-700" /></div><StatusBadge tone="neutral">Atualizado</StatusBadge></div><h2 className="mt-5 text-sm font-bold">{t}</h2><p className="mt-1 text-xs text-slate-500">{d}</p><button onClick={() => setToast(true)} className="mt-5 flex items-center gap-2 text-xs font-semibold text-blue-700"><Download className="h-4 w-4" />Preparar relatório</button></article>)}</div>{toast && <DemoToast message="Relatório preparado para exportação demonstrativa." onClose={() => setToast(false)} />}</div>;
}
